import 'package:flutter/material.dart';
import 'package:mobile_scanner/mobile_scanner.dart';
import '../models/product.dart';
import '../services/database_service.dart';
import '../services/trendyol_service.dart';
import '../widgets/product_card.dart';

class SearchScreen extends StatefulWidget { const SearchScreen({super.key}); @override State<SearchScreen> createState() => _SearchScreenState(); }
class _SearchScreenState extends State<SearchScreen> {
  final controller = TextEditingController(); final service = TrendyolService(); List<Product> products = []; bool loading = false; String? error;
  Future<void> search() async { final barcode = controller.text.trim(); if (barcode.isEmpty) return; FocusManager.instance.primaryFocus?.unfocus(); setState(() { loading = true; error = null; products = []; }); try { final result = await service.search(barcode); if (!mounted) return; if (result.error != null) { setState(() => error = result.error); } else { for (var p in result.products) { final cat = await DatabaseService.instance.category(p.categoryId); final enriched = Product(categoryId: p.categoryId, name: p.name, priceText: p.priceText, price: p.price, currency: p.currency, image: p.image, rating: p.rating, orderCount: p.orderCount, barcode: p.barcode, categoryName: cat?.name, commission: cat?.commission ?? 0); products.add(enriched); await DatabaseService.instance.saveHistory({'name': enriched.name, 'url': 'https://www.trendyol.com/sr?q=${enriched.barcode}', 'category_id': enriched.categoryId, 'price': enriched.price, 'currency': enriched.currency, 'image': enriched.image, 'rating': enriched.rating, 'order_count': enriched.orderCount, 'commission': enriched.commission, 'searched_at': DateTime.now().toIso8601String()}); } setState(() {}); } } catch (_) { if (mounted) setState(() => error = 'Arama sırasında bir hata oluştu. İnternet bağlantınızı kontrol edin.'); } finally { if (mounted) setState(() => loading = false); } }
  Future<void> scan() async { final value = await Navigator.push<String>(context, MaterialPageRoute(builder: (_) => const ScannerScreen())); if (value != null) { controller.text = value; search(); } }
  @override Widget build(BuildContext context) => Padding(padding: const EdgeInsets.fromLTRB(18, 24, 18, 8), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Ürün Sorgula', style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold)), const SizedBox(height: 6), Text('Barkod ile Trendyol ürününü ve kazancını keşfet.', style: TextStyle(color: Colors.grey.shade600)), const SizedBox(height: 20), Row(children: [Expanded(child: TextField(controller: controller, keyboardType: TextInputType.number, textInputAction: TextInputAction.search, onSubmitted: (_) => search(), decoration: const InputDecoration(labelText: 'Barkod', hintText: 'Barkod numarasını girin', prefixIcon: Icon(Icons.qr_code_2)))), const SizedBox(width: 8), IconButton.filled(onPressed: scan, icon: const Icon(Icons.camera_alt), tooltip: 'Barkod okut')]), const SizedBox(height: 18), if (loading) const LinearProgressIndicator(), if (error != null) _ErrorBox(error!), if (!loading && error == null && products.isEmpty) const Expanded(child: Center(child: Text('Aramak için bir barkod girin', style: TextStyle(color: Colors.grey)))), if (products.isNotEmpty) Expanded(child: ListView.builder(itemCount: products.length, itemBuilder: (_, i) => ProductCard(product: products[i])))]));
  Widget _ErrorBox(String text) => Container(width: double.infinity, padding: const EdgeInsets.all(14), margin: const EdgeInsets.only(bottom: 12), decoration: BoxDecoration(color: Colors.red.shade50, borderRadius: BorderRadius.circular(12)), child: Text(text, style: TextStyle(color: Colors.red.shade800)));
}
class ScannerScreen extends StatelessWidget { const ScannerScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Barkod okut')), body: MobileScanner(onDetect: (capture) { final code = capture.barcodes.isEmpty ? null : capture.barcodes.first.rawValue; if (code != null) Navigator.pop(context, code); })); }
